const extraHardQuestions = [{"s":0,"l":"A","t":"Сатушы 40 құрылғыны 2400 тг-ден алып, тасымалға 4000 тг төледі.5 құрылғы сатуға жарамсыз болды. Қалғандары бір бағамен сатылады.<br><br>Шығынды толық жабатын ең аз бүтін теңгелік сату бағасы?","o":["2857 тг","2500 тг","2858 тг","2800 тг"],"a":2,"e":"100000/35≈2857,14. Төмен дөңгелектеуге болмайды:2858.","id":61},{"s":0,"l":"B","t":"Сатушы 40 құрылғыны 2400 тг-ден алып, тасымалға 4000 тг төледі.5 құрылғы сатуға жарамсыз болды. Қалғандары бір бағамен сатылады.<br><br>Әр жарамды құрылғы 4000 тг белгіленіп,10% жеңілдікпен сатылды. Пайда шығынның неше пайызы?","o":["25%","26%","30%","20%"],"a":1,"e":"Түсім 35×4000×0,9=126000. Пайда 26000, шығын 100000, яғни 26%.","id":62},{"s":0,"l":"B","t":"Сатушы 40 құрылғыны 2400 тг-ден алып, тасымалға 4000 тг төледі.5 құрылғы сатуға жарамсыз болды. Қалғандары бір бағамен сатылады.<br><br>Жарамды 35 құрылғының 20-сы 4000 тг-ден сатылды. Қалған 15-ін бір бағамен сатып, жалпы 20000 тг пайда алу үшін олардың бағасы қанша? Бүтін теңгеге дейін жоғары дөңгелектеңіз.","o":["2666 тг","2667 тг","3000 тг","2800 тг"],"a":1,"e":"Қажетті түсім 120000. Алғашқы 80000-нан кейін 40000 керек.40000/15≈2666,67, кемінде 2667.","id":63},{"s":0,"l":"C","t":"Сатушы 40 құрылғыны 2400 тг-ден алып, тасымалға 4000 тг төледі.5 құрылғы сатуға жарамсыз болды. Қалғандары бір бағамен сатылады.<br><br>Әр құрылғыны 4000 тг-ден сатпақ.10 жарамды құрылғыға 25% жеңілдік берілді. Қалған 25-іне ең үлкен қандай пайыз жеңілдік жасаса да, жалпы түсім кемінде 120000 тг болады?","o":["8%","15%","10%","12%"],"a":2,"e":"Алғашқы 10 түсімі 30000. Қалған 25-тен 90000 керек, біреуі 3600.4000-нан 3600-ге жеңілдік 10%.","id":64},{"s":0,"l":"A","t":"Массасы 24 кг қорытпада мыс пен мырыш қатынасы 5:3. Балқыту кезінде тек мырыш буланады, мыс жоғалмайды.<br><br>Мырыштың 1/3 бөлігі буланғаннан кейін мыстың пайыздық үлесі қандай? Ондыққа дейін.","o":["71,4%","62,5%","66,7%","75%"],"a":0,"e":"Бастапқы мыс 15, мырыш 9.3 кг мырыш жоғалып, масса 21.15/21×100≈71,4%.","id":65},{"s":0,"l":"A","t":"Массасы 24 кг қорытпада мыс пен мырыш қатынасы 5:3. Балқыту кезінде тек мырыш буланады, мыс жоғалмайды.<br><br>Мыстың үлесін 75%-ға жеткізу үшін бастапқы қорытпадан неше кг мырыш булануы керек?","o":["4 кг","6 кг","3 кг","5 кг"],"a":0,"e":"Мыс 15 тұрақты.75% болуы үшін жалпы масса 20.24−20=4 кг жоғалту.","id":66},{"s":0,"l":"B","t":"Массасы 24 кг қорытпада мыс пен мырыш қатынасы 5:3. Балқыту кезінде тек мырыш буланады, мыс жоғалмайды.<br><br>Бастапқы 24 кг қорытпаға тек мыс қосып, қатынасты 3:1 етті. Қанша мыс қосылды?","o":["12 кг","9 кг","6 кг","15 кг"],"a":0,"e":"Мырыш 9 қалса, мыс 27 керек.27−15=12.","id":67},{"s":0,"l":"B","t":"Массасы 24 кг қорытпада мыс пен мырыш қатынасы 5:3. Балқыту кезінде тек мырыш буланады, мыс жоғалмайды.<br><br>Бастапқы қорытпаға 6 кг таза мырыш қосылды. Жаңа мыс үлесі бастапқы мыс үлесінен неше пайыздық пунктке төмен?","o":["20","10","15","12,5"],"a":3,"e":"Бастапқы 62,5%. Жаңа 15/30=50%. Айырма 12,5 пункт.","id":68},{"s":0,"l":"C","t":"Массасы 24 кг қорытпада мыс пен мырыш қатынасы 5:3. Балқыту кезінде тек мырыш буланады, мыс жоғалмайды.<br><br>Бастапқы қорытпаға 6 кг мыс қосып, кейін мырыш буланғанда мыс үлесі 84% болды. Буланған мырыш массасы?","o":["4 кг","6 кг","3 кг","5 кг"],"a":3,"e":"Мыс 21, жалпы масса 30. Соңғы масса 21/0,84=25. Буланғаны 30−25=5.","id":69},{"s":0,"l":"B","t":"Ашықхат 3 данадан 720 тг,5 данадан 1100 тг қаптамамен, жеке 260 тг-ден сатылады. Тек бүтін қаптама алынады.<br><br>Жеке 260 тг бағамен 14 ашықхат алумен салыстырғанда 3180 тг-лік сатып алудың үнемі неше пайыз? Ондыққа дейін.","o":["12,6%","15%","14,5%","10%"],"a":0,"e":"Жеке құн 3640. Үнем 460/3640×100≈12,6%.","id":72},{"s":0,"l":"B","t":"Ашықхат 3 данадан 720 тг,5 данадан 1100 тг қаптамамен, жеке 260 тг-ден сатылады. Тек бүтін қаптама алынады.<br><br>Екі 3-тік қаптаманың бағасы екі 5-тік қаптаманың бағасынан неше пайызға аз? Ондыққа дейін.","o":["40%","52,8%","30%","34,5%"],"a":3,"e":"(2200−1440)/2200×100≈34,5%. Негіз салыстырылып отырған 2200.","id":73},{"s":0,"l":"C","t":"Ашықхат 3 данадан 720 тг,5 данадан 1100 тг қаптамамен, жеке 260 тг-ден сатылады. Тек бүтін қаптама алынады.<br><br>Сатып алушы дәл 16 ашықхат алуы тиіс. Ең тиімді комбинацияда қанша жеке ашықхат болады?","o":["0","3","2","1"],"a":0,"e":"Екі 5-тік пен екі 3-тік дәл 16 дана:2200+1440=3640. Үш 5-тік пен бір жеке 3560 тг — бұдан арзан, сондықтан 1 жеке. Дұрыс комбинацияны толық салыстыру қажет.","id":74},{"s":0,"l":"A","t":"Кітапхана қаражатының 40%-ын кітапқа жұмсады. Содан кейін қалғанынан 18000 тг жабдыққа бөлді. Қалғанының 1/3 бөлігі жолақыға кетіп, соңында 48000 тг қалды.<br><br>Жабдыққа бөлгенге дейінгі қалдық қанша болған?","o":["60000 тг","90000 тг","72000 тг","108000 тг"],"a":1,"e":"Жолақыдан кейін 2/3 бөлік 48000, демек оған дейін 72000. Жабдықты қосамыз:90000.","id":75},{"s":0,"l":"B","t":"Кітапхана қаражатының 40%-ын кітапқа жұмсады. Содан кейін қалғанынан 18000 тг жабдыққа бөлді. Қалғанының 1/3 бөлігі жолақыға кетіп, соңында 48000 тг қалды.<br><br>Жолақы бастапқы қаражаттың неше пайызы?","o":["20%","24%","16%","12%"],"a":2,"e":"Жолақы 72000/3=24000.24000/150000=16%.","id":77},{"s":0,"l":"B","t":"Кітапхана қаражатының 40%-ын кітапқа жұмсады. Содан кейін қалғанынан 18000 тг жабдыққа бөлді. Қалғанының 1/3 бөлігі жолақыға кетіп, соңында 48000 тг қалды.<br><br>Кітапқа кеткен ақша жабдық пен жолақы қосындысынан қанша артық?","o":["18000 тг","30000 тг","24000 тг","12000 тг"],"a":0,"e":"Кітап 60000. Жабдық+жол 42000. Айырма 18000.","id":78},{"s":0,"l":"C","t":"Кітапхана қаражатының 40%-ын кітапқа жұмсады. Содан кейін қалғанынан 18000 тг жабдыққа бөлді. Қалғанының 1/3 бөлігі жолақыға кетіп, соңында 48000 тг қалды.<br><br>Жолақы 72000 қалдықтың 1/3 бөлігі емес, бастапқы қаражаттың 20%-ы болғанда, өзге шығын өзгермесе, соңында қанша қалар еді?","o":["54000 тг","36000 тг","42000 тг","48000 тг"],"a":2,"e":"Бастапқы 150000-ның 20%-ы 30000.72000−30000=42000.","id":79},{"s":0,"l":"A","t":"Өндіріс екі партия бұйымды бірлік шығыны 3000 тг-ден дайындады. Бірінші партияда 20, екіншісінде 30 бұйым бар. Бірінші партия шығыннан 40% қымбат сатылды.<br><br>Жалпы пайда барлық шығынның 20%-ына тең болуы үшін екінші партияның бірлік бағасы қандай болуы керек?","o":["3600 тг","3300 тг","3500 тг","3200 тг"],"a":3,"e":"Шығын 150000, қажетті түсім 180000. Бірінші 20×4200=84000. Қалған 96000/30=3200.","id":80},{"s":0,"l":"A","t":"Өндіріс екі партия бұйымды бірлік шығыны 3000 тг-ден дайындады. Бірінші партияда 20, екіншісінде 30 бұйым бар. Бірінші партия шығыннан 40% қымбат сатылды.<br><br>Екінші партия 3600 тг-ден сатылса, жалпы пайда шығынның неше пайызы?","o":["28%","24%","30%","32%"],"a":0,"e":"Түсім 84000+108000=192000. Пайда 42000/150000=28%.","id":81},{"s":0,"l":"B","t":"Өндіріс екі партия бұйымды бірлік шығыны 3000 тг-ден дайындады. Бірінші партияда 20, екіншісінде 30 бұйым бар. Бірінші партия шығыннан 40% қымбат сатылды.<br><br>Екінші партиядан 5 бұйым сатылмай қалды. Қалған 25-ін 3600 тг-ден сатқандағы жалпы пайда?","o":["18000 тг","24000 тг","42000 тг","30000 тг"],"a":1,"e":"Түсім 84000+90000=174000. Барлық 50 бұйым шығыны 150000. Пайда 24000.","id":82},{"s":0,"l":"B","t":"Өндіріс екі партия бұйымды бірлік шығыны 3000 тг-ден дайындады. Бірінші партияда 20, екіншісінде 30 бұйым бар. Бірінші партия шығыннан 40% қымбат сатылды.<br><br>Алдыңғы сұрақтағы 174000 тг түсімнің ішіндегі пайда үлесі қандай? Ондыққа дейін.","o":["12%","16%","13,8%","14,5%"],"a":2,"e":"24000/174000×100≈13,8%. Бұл шығынға шаққандағы 16%-дан бөлек.","id":83},{"s":0,"l":"A","t":"Турға шағын автобус 16 орындық, жалға алу 48000 тг. Үлкен автобус 28 орындық, жалға алу 76000 тг. Жүргізушілер орын санына кірмейді.<br><br>Кемінде 72 жолаушы үшін екі үлкенге қосымша неше шағын керек және құны қандай?","o":["1 шағын,192000 тг","0 шағын,152000 тг","1 шағын,200000 тг","2 шағын,248000 тг"],"a":2,"e":"2 үлкен 56 орын, тағы 16 керек.1 шағынмен 72 орын,152000+48000=200000.","id":86},{"s":0,"l":"B","t":"Турға шағын автобус 16 орындық, жалға алу 48000 тг. Үлкен автобус 28 орындық, жалға алу 76000 тг. Жүргізушілер орын санына кірмейді.<br><br>72 жолаушының бәрі тең төлесе,200000 тг жалдауды жабатын ең аз бүтін теңгелік төлем?","o":["2778 тг","2777 тг","2800 тг","2750 тг"],"a":0,"e":"200000/72≈2777,78. Кемінде 2778 тг.","id":87},{"s":0,"l":"B","t":"Турға шағын автобус 16 орындық, жалға алу 48000 тг. Үлкен автобус 28 орындық, жалға алу 76000 тг. Жүргізушілер орын санына кірмейді.<br><br>Үлкен автобусқа 5% жеңілдік бар, шағынға жоқ. Екі үлкен және бір шағынның жаңа ақысы?","o":["194000 тг","192400 тг","196200 тг","190000 тг"],"a":1,"e":"152000×0,95+48000=144400+48000=192400.","id":88},{"s":0,"l":"C","t":"Турға шағын автобус 16 орындық, жалға алу 48000 тг. Үлкен автобус 28 орындық, жалға алу 76000 тг. Жүргізушілер орын санына кірмейді.<br><br>60 адам үшін үлкенге 5% жеңілдік берілгенде ең арзан комбинацияның құны?","o":["168200 тг","192000 тг","182400 тг","216600 тг"],"a":0,"e":"1 үлкен+2 шағын:72200+96000=168200.4 шағын 192000,3 үлкен 216600,2 үлкен+шағын 192400.","id":89},{"s":0,"l":"A","t":"Кофе қоспасы А-да 60% арабика,B-де 90% арабика. Қалғаны робуста. Біркелкі 20 кг қоспа дайындайды.<br><br>Арабика үлесі 72% болу үшінB қоспасынан неше кг керек?","o":["10 кг","6 кг","8 кг","12 кг"],"a":2,"e":"0,6(20−x)+0,9x=14,4 →0,3x=2,4 →x=8.","id":90},{"s":0,"l":"A","t":"Кофе қоспасы А-да 60% арабика,B-де 90% арабика. Қалғаны робуста. Біркелкі 20 кг қоспа дайындайды.<br><br>Осы 72%-дық қоспадан 5 кг сатылғаннан кейінгі арабика массасы қанша?","o":["10,8 кг","12 кг","14,4 кг","9 кг"],"a":0,"e":"Біркелкі қоспада қалған 15 кг-ның 72%-ы 10,8.","id":91},{"s":0,"l":"B","t":"Кофе қоспасы А-да 60% арабика,B-де 90% арабика. Қалғаны робуста. Біркелкі 20 кг қоспа дайындайды.<br><br>Қалған 15 кг қоспаға 3 кг таза робуста қосылса, арабика үлесі?","o":["60%","65%","62%","54%"],"a":0,"e":"Арабика 10,8 кг өзгермейді. Жалпы 18 кг,10,8/18=60%.","id":92},{"s":0,"l":"B","t":"Кофе қоспасы А-да 60% арабика,B-де 90% арабика. Қалғаны робуста. Біркелкі 20 кг қоспа дайындайды.<br><br>Бастапқы 20 кг 72%-дық қоспаға таза арабика қосып,80% етті. Қанша арабика қосылды?","o":["8 кг","6 кг","4 кг","10 кг"],"a":0,"e":"(14,4+x)/(20+x)=0,8 →0,2x=1,6 →x=8.","id":93},{"s":0,"l":"C","t":"Кофе қоспасы А-да 60% арабика,B-де 90% арабика. Қалғаны робуста. Біркелкі 20 кг қоспа дайындайды.<br><br>Бастапқы 20 кг 72%-дық қоспадан 4 кг алынып, орнына 4 кгB қоспасы құйылды. Жаңа арабика үлесі?","o":["78%","74,4%","75,6%","76%"],"a":2,"e":"Қалған 16 кг-да 11,52 кг арабика,B4 кг-да 3,6. Барлығы 15,12/20=75,6%.","id":94},{"s":0,"l":"A","t":"Баспа бағасы: алғашқы 200 данаға тұрақты 9000 тг, әр келесі данаға 35 тг. Екі тапсырыс бөлек берілсе, тұрақты ақы әрқайсысына алынады.<br><br>350 дана тапсырыстың орташа бір даналық бағасы?","o":["35 тг","285/7 тг","900/7 тг","45 тг"],"a":1,"e":"Толық 9000+150×35=14250.14250/350=285/7≈40,71 тг.","id":95},{"s":0,"l":"A","t":"Баспа бағасы: алғашқы 200 данаға тұрақты 9000 тг, әр келесі данаға 35 тг. Екі тапсырыс бөлек берілсе, тұрақты ақы әрқайсысына алынады.<br><br>240 және 160 даналық екі тапсырысты бірге бергендегі үнем қанша?","o":["3400 тг","9000 тг","2000 тг","5600 тг"],"a":0,"e":"Бөлек 10400+9000=19400. Бірге 400 дана 16000. Үнем 3400.","id":96},{"s":0,"l":"B","t":"Баспа бағасы: алғашқы 200 данаға тұрақты 9000 тг, әр келесі данаға 35 тг. Екі тапсырыс бөлек берілсе, тұрақты ақы әрқайсысына алынады.<br><br>Бюджет 19500 тг болса, ең көп неше дана басылады?","o":["500","450","550","557"],"a":0,"e":"Қосымша(19500−9000)/35=300 дана.200+300=500.","id":97},{"s":0,"l":"B","t":"Баспа бағасы: алғашқы 200 данаға тұрақты 9000 тг, әр келесі данаға 35 тг. Екі тапсырыс бөлек берілсе, тұрақты ақы әрқайсысына алынады.<br><br>350 дананың 14250 тг ақысына 12% салық қосылады. Бір тапсырыстың толық төлемі?","o":["16000 тг","17100 тг","15960 тг","15450 тг"],"a":2,"e":"14250×1,12=15960.","id":98},{"s":0,"l":"C","t":"Баспа бағасы: алғашқы 200 данаға тұрақты 9000 тг, әр келесі данаға 35 тг. Екі тапсырыс бөлек берілсе, тұрақты ақы әрқайсысына алынады.<br><br>Басқа баспа тұрақты ақысыз, әр дана 45 тг алады.200 данадан көп тапсырыста бірінші баспа алғаш қай бүтін данадан бастап арзанырақ?","o":["400","200","300","201"],"a":3,"e":"n>200 үшін бірінші 9000+35(n−200)=2000+35n.45n-нен арзан болу үшінn>200. Алғаш 201.","id":99},{"s":0,"l":"A","t":"Топта бастапқыда қыздар ұлдардан 50% көп.6 ұл қосылып,4 қыз кеткеннен кейін екі топтың саны тең болды.<br><br>Бастапқы ұлдар саны?","o":["16","24","20","12"],"a":2,"e":"Ұлx, қыз 1,5x. x+6=1,5x−4 →0,5x=10 →x=20.","id":100},{"s":0,"l":"A","t":"Топта бастапқыда қыздар ұлдардан 50% көп.6 ұл қосылып,4 қыз кеткеннен кейін екі топтың саны тең болды.<br><br>Бастапқы топтағы қыздар үлесі?","o":["50%","60%","66,7%","55%"],"a":1,"e":"Қыз 30, барлығы 50.30/50=60%.","id":101},{"s":0,"l":"B","t":"Топта бастапқыда қыздар ұлдардан 50% көп.6 ұл қосылып,4 қыз кеткеннен кейін екі топтың саны тең болды.<br><br>Өзгерістен кейінгі жалпы адам саны?","o":["50","54","52","48"],"a":2,"e":"Ұл 26, қыз 26, барлығы 52.","id":102},{"s":0,"l":"B","t":"Топта бастапқыда қыздар ұлдардан 50% көп.6 ұл қосылып,4 қыз кеткеннен кейін екі топтың саны тең болды.<br><br>Өзгерістен кейін ұлдар саны бастапқыдан неше пайызға артты?","o":["25%","23,1%","20%","30%"],"a":3,"e":"6/20×100=30%.","id":103},{"s":0,"l":"C","t":"Топта бастапқыда қыздар ұлдардан 50% көп.6 ұл қосылып,4 қыз кеткеннен кейін екі топтың саны тең болды.<br><br>Өзгерістен кейін қыздар үлесін қайта 60% ету үшін тек қыздар қосылады. Ең аз неше қыз қосу керек?","o":["12","15","13","10"],"a":2,"e":"(26+y)/(52+y)=0,6 →0,4y=5,2 →y=13.","id":104},{"s":0,"l":"A","t":"Қайтарылатын қораппен сусын алу: сусын 1200 тг, қорап кепілі 300 тг. Әр қайтарылған қорапқа кепіл толық қайтады.10 сусын сатып алынды.<br><br>Сатып алушы 7 қорапты қайтарса, оның таза шығыны қанша?","o":["12900 тг","14100 тг","15000 тг","12000 тг"],"a":0,"e":"Алғаш 10×1500=15000 төледі.7×300=2100 қайтты. Таза 12900.","id":105},{"s":0,"l":"A","t":"Қайтарылатын қораппен сусын алу: сусын 1200 тг, қорап кепілі 300 тг. Әр қайтарылған қорапқа кепіл толық қайтады.10 сусын сатып алынды.<br><br>Барлық қорап қайтарылғанда бастапқы төлемнің қанша пайызы кері қайтады?","o":["30%","20%","15%","25%"],"a":1,"e":"3000/15000×100=20%.","id":106},{"s":0,"l":"B","t":"Қайтарылатын қораппен сусын алу: сусын 1200 тг, қорап кепілі 300 тг. Әр қайтарылған қорапқа кепіл толық қайтады.10 сусын сатып алынды.<br><br>Сатып алушының таза шығыны 12600 тг болды. Неше қорап қайтарылмады?","o":["3","4","8","2"],"a":3,"e":"Сусындардың құны 12000. Артық 600 тг —2 кепіл.","id":107},{"s":0,"l":"B","t":"Қайтарылатын қораппен сусын алу: сусын 1200 тг, қорап кепілі 300 тг. Әр қайтарылған қорапқа кепіл толық қайтады.10 сусын сатып алынды.<br><br>10 сусыннан кейін 300 тг кепілі бар 8 қорап қайтарылды. Қайтарымға қосымша ең аз қанша ақша қосса, кепілімен тағы 2 сусын алады?","o":["600 тг","900 тг","1200 тг","300 тг"],"a":0,"e":"Қайтарым 2400, екі сусын кепілімен 3000. Қосу 600.","id":108},{"s":0,"l":"C","t":"Қайтарылатын қораппен сусын алу: сусын 1200 тг, қорап кепілі 300 тг. Әр қайтарылған қорапқа кепіл толық қайтады.10 сусын сатып алынды.<br><br>10 сусынға тек сусын құнынан 15% жеңілдік жасалды, кепіл өзгермейді.6 қорап қайтарылса, таза шығын қанша?","o":["10200 тг","10950 тг","12000 тг","11400 тг"],"a":3,"e":"Сусын 10200+кепіл 3000=13200. Қайтарым 1800. Таза 11400.","id":109},{"s":1,"l":"A","t":"Екі топтың орташа ұпайлары берілген. А тобында 15 адам, орташа 72. B тобында 25 адам, орташа 84.<br><br>Екі топтың жалпы орташа ұпайы?","o":["78","81","79,5","80"],"a":2,"e":"Қосынды 15×72+25×84=3180.40 адамға 3180/40=79,5.","id":110},{"s":1,"l":"A","t":"Екі топтың орташа ұпайлары берілген. А тобында 15 адам, орташа 72. B тобында 25 адам, орташа 84.<br><br>B тобынан 100 ұпайлы бір адам шықса, қалған 39 адамның орташа ұпайы қанша? Екі ондық таңбаға дейін.","o":["78,5","78,97","79","80"],"a":1,"e":"Жаңа қосынды 3080.3080/39≈78,97.","id":111},{"s":1,"l":"B","t":"Екі топтың орташа ұпайлары берілген. А тобында 15 адам, орташа 72. B тобында 25 адам, орташа 84.<br><br>А тобынаx ұпайлы бір адам қосылғанда топ орташа 75 болды. x қанша?","o":["108","120","100","117"],"a":1,"e":"16×75−15×72=120.","id":112},{"s":1,"l":"B","t":"Екі топтың орташа ұпайлары берілген. А тобында 15 адам, орташа 72. B тобында 25 адам, орташа 84.<br><br>А тобынан 60 ұпайлы бір адам B тобына ауысты. Жаңа B тобының орташа ұпайы? Екі ондық таңбаға дейін.","o":["84,92","82,5","83,08","85"],"a":2,"e":"B қосынды 2100+60=2160, саны 26.2160/26≈83,08.","id":113},{"s":1,"l":"C","t":"Екі топтың орташа ұпайлары берілген. А тобында 15 адам, орташа 72. B тобында 25 адам, орташа 84.<br><br>Екі топқа бірдейx ұпайлы бір адамнан қосылды. Әр ұпай 0-ден 100-ге дейін. Екі топтың жаңа орташа ұпайларын осы тәсілмен теңестіруге бола ма?","o":["Жоқ, теңестіру үшін 552 ұпай керек","Иә,100 ұпаймен","Иә,84 ұпаймен","Иә,72 ұпаймен"],"a":0,"e":"(1080+x)/16=(2100+x)/26 →10x=5520 →x=552. Бұл 0..100 аралығынан тыс, сондықтан рұқсат етілген ұпаймен теңестіру мүмкін емес.","id":114},{"s":1,"l":"A","t":"Қапта 5 ақ,4 қара,3 қызыл шар бар. Шарлар кері салынбай алынады.<br><br>Алғашқы екі шардың екеуі де ақ болу ықтималдығы?","o":["5/12","5/33","25/144","1/6"],"a":1,"e":"5/12×4/11=20/132=5/33.","id":115},{"s":1,"l":"A","t":"Қапта 5 ақ,4 қара,3 қызыл шар бар. Шарлар кері салынбай алынады.<br><br>Алғашқы екі шардың дәл біреуі қызыл болу ықтималдығы?","o":["1/2","3/22","3/11","9/22"],"a":3,"e":"2×3/12×9/11=54/132=9/22.","id":116},{"s":1,"l":"B","t":"Қапта 5 ақ,4 қара,3 қызыл шар бар. Шарлар кері салынбай алынады.<br><br>Үш шардың бәрі әртүрлі түсті болу ықтималдығы?","o":["1/3","3/11","1/4","5/22"],"a":1,"e":"Әр түстен біреу:5×4×3=60 ретсіз топ. БарлықC(12,3)=220.60/220=3/11.","id":117},{"s":1,"l":"B","t":"Қапта 5 ақ,4 қара,3 қызыл шар бар. Шарлар кері салынбай алынады.<br><br>Екі шар алғанда кемінде біреуі қара болу ықтималдығы?","o":["1/3","14/33","2/3","19/33"],"a":3,"e":"Қара емес 8 шар. Қарсы оқиғаC(8,2)/C(12,2)=28/66.1−28/66=19/33.","id":118},{"s":1,"l":"C","t":"Қапта 5 ақ,4 қара,3 қызыл шар бар. Шарлар кері салынбай алынады.<br><br>Алынған екі шардың түстері бірдей екені белгілі. Екеуі ақ болуының ықтималдығы?","o":["10/19","5/11","1/2","5/12"],"a":0,"e":"Бір түсті жұптарC(5,2)+C(4,2)+C(3,2)=10+6+3=19. Ақ жұп 10, шартты ықтималдық 10/19.","id":119},{"s":1,"l":"A","t":"Деректер өсу ретімен:2,5,7,a,11,13,b. Құлашы 18, орташа мәні белгісіз.<br><br>b мәні?","o":["20","22","18","16"],"a":0,"e":"Құлашb−2=18 →b=20. Қосымша орташа шарты a-ны анықтайды.","id":120},{"s":1,"l":"A","t":"Деректер өсу ретімен:2,5,7,a,11,13,b. Құлашы 18, орташа мәні белгісіз.<br><br>Орташа мән 10 деген қосымша хабарлама өсу ретімен үйлесе ме?","o":["Жоқ, шарттар қайшы","Иә,a=12","Иә,a=10","Иә,a=8"],"a":0,"e":"Жалпы қосынды 70, белгілі 2+5+7+11+13+20=58. a=12, бірақ a≤11 болуы тиіс. Шарттар қайшы, мұндай қатар жоқ.","id":121},{"s":1,"l":"B","t":"Деректер өсу ретімен:2,5,7,a,11,13,b. Құлашы 18, орташа мәні белгісіз.<br><br>Егер өсу реті талабы алынып тасталса,a=12,b=20 деректерінің медианасы?","o":["11","7","12","10"],"a":0,"e":"Реттелген 2,5,7,11,12,13,20. Медиана 11.","id":122},{"s":1,"l":"B","t":"Деректер өсу ретімен:2,5,7,a,11,13,b. Құлашы 18, орташа мәні белгісіз.<br><br>Өсу реті талабын алып тастағанда a=12,b=20. Орташаға тең болатын сан тізімде бар ма?","o":["Иә,10 бар","Иә,12 бар","Иә,11 бар","Жоқ"],"a":3,"e":"Орташа 10, бірақ тізімде 10 жоқ. Орташа міндетті түрде деректердің бірі емес.","id":123},{"s":1,"l":"C","t":"Деректер өсу ретімен:2,5,7,a,11,13,b. Құлашы 18, орташа мәні белгісіз.<br><br>Өсу реті сақталсын, құлаш 18 болып қалсын, ал орташа 10 шарты өзгертілсін. Орташа мәннің ең үлкен мүмкін мәні?","o":["69/7","11","10","68/7"],"a":0,"e":"b=20,a≤11. Ең үлкен қосынды 58+11=69, орташа 69/7≈9,857.","id":124},{"s":1,"l":"A","t":"Жарыста 6 қыз және 5 ұл бар. Кездейсоқ 4 адамдық команда таңдалады.<br><br>Дәл 3 қыз,1 ұл болатын команда саны?","o":["100","120","60","80"],"a":0,"e":"C(6,3)×C(5,1)=20×5=100.","id":125},{"s":1,"l":"B","t":"Жарыста 6 қыз және 5 ұл бар. Кездейсоқ 4 адамдық команда таңдалады.<br><br>Кемінде 3 қыз бар команда ықтималдығы?","o":["5/11","7/22","23/66","1/3"],"a":2,"e":"3 қыз 1 ұл 100 тәсіл,4 қызC(6,4)=15. БарлығыC(11,4)=330.115/330=23/66.","id":127},{"s":1,"l":"B","t":"Жарыста 6 қыз және 5 ұл бар. Кездейсоқ 4 адамдық команда таңдалады.<br><br>Екі нақты қыз бірге командаға кірсе, қалған екі орынды неше тәсілмен толтыруға болады?","o":["72","45","28","36"],"a":3,"e":"Қалған 9 адамнан 2:C(9,2)=36.","id":128},{"s":1,"l":"C","t":"Жарыста 6 қыз және 5 ұл бар. Кездейсоқ 4 адамдық команда таңдалады.<br><br>Бір нақты қызбен бір нақты ұл командада бірге болмауы керек. Жарамды 4 адамдық командалар саны?","o":["294","258","300","286"],"a":0,"e":"Барлық 330. Екеуі бірге болса, қалған 9-дан 2 таңдау 36.330−36=294.","id":129},{"s":1,"l":"A","t":"A қорапта 3 алтын,2 күміс белгі;B қорапта 1 алтын,4 күміс белгі бар. Қорап тең ықтималдықпен таңдалады.<br><br>Алынған бір белгі алтын болу ықтималдығы?","o":["1/2","2/5","3/5","1/5"],"a":1,"e":"1/2×3/5+1/2×1/5=2/5.","id":130},{"s":1,"l":"B","t":"A қорапта 3 алтын,2 күміс белгі;B қорапта 1 алтын,4 күміс белгі бар. Қорап тең ықтималдықпен таңдалады.<br><br>Таңдалған қораптан екі белгі кері салынбай алынады. Екеуі алтын ықтималдығы?","o":["1/10","3/20","1/5","3/10"],"a":1,"e":"A үшін 3/5×2/4=3/10,B үшін 0. Орташа 1/2×3/10=3/20.","id":132},{"s":1,"l":"B","t":"A қорапта 3 алтын,2 күміс белгі;B қорапта 1 алтын,4 күміс белгі бар. Қорап тең ықтималдықпен таңдалады.<br><br>Екі белгі алтын шыққаны белгілі болса, қорапB болу ықтималдығы?","o":["1/3","0","1/5","1/2"],"a":1,"e":"B-де бір ғана алтын, екі алтын алу мүмкін емес.","id":133},{"s":1,"l":"C","t":"A қорапта 3 алтын,2 күміс белгі;B қорапта 1 алтын,4 күміс белгі бар. Қорап тең ықтималдықпен таңдалады.<br><br>Бір белгі алынды, кері салынды, сол қораптан тағы алынды. Екеуі алтын болса, қорапA болуының ықтималдығы?","o":["3/5","3/4","1","9/10"],"a":3,"e":"A және екі алтын:0,5×(3/5)²=9/50. B және екі алтын 1/50. Қатынас 9/10.","id":134},{"s":1,"l":"A","t":"Екі әділ сүйек лақтырылды.36 реттелген нәтиже тең ықтималды.<br><br>Қосындысы 9 және бірінші сан екіншісінен үлкен болу ықтималдығы?","o":["1/12","1/18","1/6","1/9"],"a":1,"e":"Қолайлы(5,4),(6,3), екі нәтиже.2/36=1/18.","id":135},{"s":1,"l":"A","t":"Екі әділ сүйек лақтырылды.36 реттелген нәтиже тең ықтималды.<br><br>Қосындысы 9 болғаны белгілі. Бірінші сан жұп болу ықтималдығы?","o":["1/3","1/4","1/2","2/3"],"a":2,"e":"(3,6),(4,5),(5,4),(6,3). Біріншісі жұп 2/4=1/2.","id":136},{"s":1,"l":"B","t":"Екі әділ сүйек лақтырылды.36 реттелген нәтиже тең ықтималды.<br><br>Кемінде бір сүйекте 6 түскені белгілі. Қосындысы 10 болу ықтималдығы?","o":["1/11","2/11","1/18","1/6"],"a":1,"e":"Кемінде бір 6 болатын 11 нәтиже. Қосынды 10 үшін(6,4),(4,6), яғни 2/11.","id":137},{"s":1,"l":"B","t":"Екі әділ сүйек лақтырылды.36 реттелген нәтиже тең ықтималды.<br><br>Ең үлкен түскен сан 4 болуының ықтималдығы?","o":["1/4","1/6","1/9","7/36"],"a":3,"e":"Барлығы≤4 болатын 16 нәтижеден барлығы≤3 болатын 9-ды аламыз:7/36.","id":138},{"s":1,"l":"C","t":"Екі әділ сүйек лақтырылды.36 реттелген нәтиже тең ықтималды.<br><br>Қосындысы 8 немесе көбейтіндісі 12 болатын нәтиженің ықтималдығы?","o":["1/4","5/18","2/9","7/36"],"a":3,"e":"Қосынды 8:5 нәтиже. Көбейтінді 12:(2,6),(3,4),(4,3),(6,2),4 нәтиже. Ортақ(2,6),(6,2),2.5+4−2=7.","id":139},{"s":1,"l":"A","t":"0,1,2,3,4,5 цифрларынан цифрлары қайталанбайтын үш таңбалы сандар құралады.<br><br>Барлық осындай сандар саны?","o":["120","60","125","100"],"a":3,"e":"Жүздікке 0 емес 5, ондыққа 5, бірлікке 4 таңдау:100.","id":140},{"s":1,"l":"A","t":"0,1,2,3,4,5 цифрларынан цифрлары қайталанбайтын үш таңбалы сандар құралады.<br><br>5-ке бөлінетін осындай сандар саны?","o":["40","36","20","32"],"a":1,"e":"Соңғы 0 болса 5×4=20. Соңғы 5 болса жүздікке 4, ондыққа 4:16. Барлығы 36.","id":141},{"s":1,"l":"B","t":"0,1,2,3,4,5 цифрларынан цифрлары қайталанбайтын үш таңбалы сандар құралады.<br><br>Жұп осындай сандар саны?","o":["52","60","48","50"],"a":0,"e":"Соңғы 0:20. Соңғы 2 немесе 4: әрқайсысында 4×4=16.20+32=52.","id":142},{"s":1,"l":"B","t":"0,1,2,3,4,5 цифрларынан цифрлары қайталанбайтын үш таңбалы сандар құралады.<br><br>300-ден үлкен осындай сандар саны?","o":["60","50","40","80"],"a":0,"e":"Жүздік 3,4,5:3 таңдау, қалған 5×4.3×20=60.","id":143},{"s":1,"l":"A","t":"Сауалнамада 80 адамның 50-і жаңалықты телефоннан,35-і теледидардан,25-і радиодан алады. Жұптық қиылыстар: телефон-теледидар 20, телефон-радио 15, теледидар-радио 10. Үшеуін де 8 адам қолданады.<br><br>Кемінде біреуін қолданатындар саны?","o":["70","73","65","80"],"a":1,"e":"50+35+25−20−15−10+8=73.","id":145},{"s":1,"l":"A","t":"Сауалнамада 80 адамның 50-і жаңалықты телефоннан,35-і теледидардан,25-і радиодан алады. Жұптық қиылыстар: телефон-теледидар 20, телефон-радио 15, теледидар-радио 10. Үшеуін де 8 адам қолданады.<br><br>Тек телефон қолданатындар саны?","o":["15","23","18","30"],"a":1,"e":"50−20−15+8=23.","id":146},{"s":1,"l":"B","t":"Сауалнамада 80 адамның 50-і жаңалықты телефоннан,35-і теледидардан,25-і радиодан алады. Жұптық қиылыстар: телефон-теледидар 20, телефон-радио 15, теледидар-радио 10. Үшеуін де 8 адам қолданады.<br><br>Дәл екі арна қолданатындар саны?","o":["21","37","29","45"],"a":0,"e":"Жұп қиылыстар қосындысы 45. Үштік 8 әр жұпта бар, дәл екі үшін 45−3×8=21.","id":147},{"s":1,"l":"B","t":"Сауалнамада 80 адамның 50-і жаңалықты телефоннан,35-і теледидардан,25-і радиодан алады. Жұптық қиылыстар: телефон-теледидар 20, телефон-радио 15, теледидар-радио 10. Үшеуін де 8 адам қолданады.<br><br>Ешбірін қолданбайтындар үлесі?","o":["1/10","7/80","1/8","3/16"],"a":1,"e":"80−73=7. Үлесі 7/80.","id":148},{"s":1,"l":"C","t":"Сауалнамада 80 адамның 50-і жаңалықты телефоннан,35-і теледидардан,25-і радиодан алады. Жұптық қиылыстар: телефон-теледидар 20, телефон-радио 15, теледидар-радио 10. Үшеуін де 8 адам қолданады.<br><br>Телефон қолданатыны белгілі адам кездейсоқ таңдалды. Оның өзге екі арнаның ешқайсысын қолданбау ықтималдығы?","o":["27/50","23/50","1/2","23/80"],"a":1,"e":"Шартты кеңістік 50 телефон қолданушысы, қолайлы тек телефон 23.23/50.","id":149},{"s":1,"l":"A","t":"Бағалау жүйесінде жобаның 40%-ы тест,35%-ы практика,25%-ы қорғау ұпайынан тұрады. Әр бөлік 100 ұпайдан.<br><br>Тест 80, практика 90, қорғау 60 болса, қорытынды ұпай?","o":["78,5","79","80","76,67"],"a":0,"e":"0,4×80+0,35×90+0,25×60=32+31,5+15=78,5.","id":150},{"s":1,"l":"A","t":"Бағалау жүйесінде жобаның 40%-ы тест,35%-ы практика,25%-ы қорғау ұпайынан тұрады. Әр бөлік 100 ұпайдан.<br><br>Тест 70, практика 80. Қорытынды кемінде 80 болуы үшін қорғау ұпайы кемінде қанша?","o":["96","92","90","100"],"a":0,"e":"28+28+0,25x≥80 →x≥96.","id":151},{"s":1,"l":"B","t":"Бағалау жүйесінде жобаның 40%-ы тест,35%-ы практика,25%-ы қорғау ұпайынан тұрады. Әр бөлік 100 ұпайдан.<br><br>Практика ұпайы 10-ға өсіп, тест өзгермесе, сол қорытындыны сақтау үшін қорғау ұпайы қаншаға кемуі мүмкін?","o":["12","10","16","14"],"a":3,"e":"Практика өсімі 3,5 қорытынды ұпай. Қорғауда 0,25x=3,5 →x=14.","id":152},{"s":1,"l":"B","t":"Бағалау жүйесінде жобаның 40%-ы тест,35%-ы практика,25%-ы қорғау ұпайынан тұрады. Әр бөлік 100 ұпайдан.<br><br>Тест пен практика бірдейx, қорғау 100. Қорытынды 85 болса,x қанша?","o":["75","90","80","85"],"a":2,"e":"0,75x+25=85 →x=80.","id":153},{"s":1,"l":"C","t":"Бағалау жүйесінде жобаның 40%-ы тест,35%-ы практика,25%-ы қорғау ұпайынан тұрады. Әр бөлік 100 ұпайдан.<br><br>Тест 60, практика 70 болып бекіді. Тіпті қорғау 100 болса да, қорытынды 80-ге жету мүмкін бе?","o":["Жоқ, ең көбі 73,5","Иә, дәл 80","Иә, ең көбі 83,5","Жоқ, ең көбі 70"],"a":0,"e":"24+24,5+25=73,5&lt;80. Шектеулі максимумды есептеу керек.","id":154},{"s":1,"l":"A","t":"Қоймадағы екі сөренің бірін таңдау ықтималдығы А үшін 2/3,B үшін 1/3. A сөресіндегі тауардың 10%-ы,B сөресіндегінің 40%-ы ақаулы.<br><br>Кездейсоқ таңдалған тауардың ақаулы болу ықтималдығы?","o":["1/4","3/10","1/5","1/10"],"a":2,"e":"2/3×0,1+1/3×0,4=0,2=1/5.","id":155},{"s":1,"l":"A","t":"Қоймадағы екі сөренің бірін таңдау ықтималдығы А үшін 2/3,B үшін 1/3. A сөресіндегі тауардың 10%-ы,B сөресіндегінің 40%-ы ақаулы.<br><br>Ақаусыз тауар алу ықтималдығы?","o":["3/4","4/5","7/10","9/10"],"a":1,"e":"Толық ықтималдық бойынша ақау үлесі (2/3)×0,1+(1/3)×0,4=0,2. Ақаусыз өнім ықтималдығы 1−0,2=0,8.","id":156},{"s":1,"l":"B","t":"Қоймадағы екі сөренің бірін таңдау ықтималдығы А үшін 2/3,B үшін 1/3. A сөресіндегі тауардың 10%-ы,B сөресіндегінің 40%-ы ақаулы.<br><br>Тауардың ақаулы екені белгілі. ОныңB сөресінен алыну ықтималдығы?","o":["2/3","1/3","4/5","1/2"],"a":0,"e":"(1/3×0,4)/0,2=2/3.","id":157},{"s":1,"l":"B","t":"Қоймадағы екі сөренің бірін таңдау ықтималдығы А үшін 2/3,B үшін 1/3. A сөресіндегі тауардың 10%-ы,B сөресіндегінің 40%-ы ақаулы.<br><br>Тауардың ақаусыз екені белгілі. ОныңA сөресінен алыну ықтималдығы?","o":["2/3","4/5","1/2","3/4"],"a":3,"e":"(2/3×0,9)/0,8=0,6/0,8=3/4.","id":158},{"s":1,"l":"C","t":"Қоймадағы екі сөренің бірін таңдау ықтималдығы А үшін 2/3,B үшін 1/3. A сөресіндегі тауардың 10%-ы,B сөресіндегінің 40%-ы ақаулы.<br><br>Сөре бір рет таңдалып, одан екі тәуелсіз тауар алынады. Екеуі де ақаулы болса, сөреB болуының ықтималдығы?","o":["2/3","16/17","4/5","8/9"],"a":3,"e":"B және екі ақаулы=(1/3)×0,4²=0,16/3. A үшін(2/3)×0,1²=0,02/3. Қатынас 0,16/0,18=8/9.","id":159},{"s":2,"l":"A","t":"Бірінші велосипедші 08:00-де 15 км/сағ-пен шықты. Екіншісі сол жолмен 09:20-да 25 км/сағ-пен шықты.<br><br>Кездескен орын бастапқы нүктеден неше км?","o":["50","45","60","40"],"a":0,"e":"Екінші 2 сағат×25=50. Бірінші 10/3 сағат×15=50.","id":161},{"s":2,"l":"B","t":"Бірінші велосипедші 08:00-де 15 км/сағ-пен шықты. Екіншісі сол жолмен 09:20-да 25 км/сағ-пен шықты.<br><br>Екіншісі қуып жеткенге дейін 20 минут тоқтаса, қуып жету уақыты қаншаға кешігеді?","o":["40 минут","50 минут","30 минут","20 минут"],"a":1,"e":"Тоқтаудан айырылатын жол 25×1/3=25/3 км. Оны 10 км/сағ салыстырмалы жылдамдықпен өтеуге 5/6 сағат=50 минут қосылады.","id":162},{"s":2,"l":"B","t":"Бірінші велосипедші 08:00-де 15 км/сағ-пен шықты. Екіншісі сол жолмен 09:20-да 25 км/сағ-пен шықты.<br><br>Екіншісі 1 сағат жүрген соң 10 минут тоқтап, қайта 25 км/сағ-пен жүрді. Қуып жеткенде ол жалпы неше км жүрген?","o":["55 км","56,25 км","62,5 км","50 км"],"a":1,"e":"Алғашқы сағаттан соң ара 10 км. Тоқтауда бірінші 2,5 км жүреді, ара 12,5. Қалған қуу 1,25 сағ. Екіншінің қозғалысы 2,25 сағ×25=56,25.","id":163},{"s":2,"l":"C","t":"Бірінші велосипедші 08:00-де 15 км/сағ-пен шықты. Екіншісі сол жолмен 09:20-да 25 км/сағ-пен шықты.<br><br>Екінші велосипедші 09:20-дан кейін 30 минут кешірек шықты.11:20-да біріншіге жету үшін оның тұрақты жылдамдығы қандай болуы керек?","o":["100/3 км/сағ","35 км/сағ","40 км/сағ","30 км/сағ"],"a":0,"e":"Шығуы 09:50,11:20-ға дейін 1,5 сағат. Біріншінің 11:20-дағы орны 50 км. Жылдамдық 50/1,5=100/3.","id":164},{"s":2,"l":"A","t":"КранA бассейнді 12 сағатта, B18 сағатта толтырады. Ағызғыш толық бассейнді 36 сағатта босатады. Барлық өнімділік тұрақты.<br><br>Үшеуі бірге ашылса, бос бассейн қанша сағатта толады?","o":["9","6","8","12"],"a":0,"e":"Таза 1/12+1/18−1/36=4/36=1/9. Уақыт 9 сағат.","id":165},{"s":2,"l":"A","t":"КранA бассейнді 12 сағатта, B18 сағатта толтырады. Ағызғыш толық бассейнді 36 сағатта босатады. Барлық өнімділік тұрақты.<br><br>A мен ағызғыш 3 сағат, кейін текB жұмыс істесе, қалған бөліктіB неше сағатта толтырады?","o":["16","12","15","18"],"a":2,"e":"Алғаш 3(1/12−1/36)=1/6 толды. Қалған 5/6×18=15.","id":166},{"s":2,"l":"B","t":"КранA бассейнді 12 сағатта, B18 сағатта толтырады. Ағызғыш толық бассейнді 36 сағатта босатады. Барлық өнімділік тұрақты.<br><br>Алғашқы 2 сағатA жәнеB бірге істеп, кейін екеуі жабылып, ағызғыш ашылды. Жиналған су неше сағатта ағады?","o":["9","10","12","8"],"a":1,"e":"Екі сағатта 2×5/36=5/18 бассейн. Ағызу уақыты(5/18)×36=10.","id":167},{"s":2,"l":"B","t":"КранA бассейнді 12 сағатта, B18 сағатта толтырады. Ағызғыш толық бассейнді 36 сағатта босатады. Барлық өнімділік тұрақты.<br><br>Бассейн жартылай толы. Үшеуі бірге ашылды. Толық толуына қанша уақыт керек?","o":["4,5 сағат","9 сағат","6 сағат","3,6 сағат"],"a":0,"e":"Қалған 1/2 көлем, таза жылдамдық 1/9. Уақыт 4,5 сағ.","id":168},{"s":2,"l":"C","t":"КранA бассейнді 12 сағатта, B18 сағатта толтырады. Ағызғыш толық бассейнді 36 сағатта босатады. Барлық өнімділік тұрақты.<br><br>Бос бассейндеA жәнеB2 сағат жұмыс істеді. КейінB жабылып,A мен ағызғыш ашық қалды. Басталғаннан толғанға дейінгі жалпы уақыт?","o":["13 сағат","16 сағат","14 сағат","15 сағат"],"a":3,"e":"Алғаш 5/18 толды,13/18 қалды. Жаңа жылдамдық 1/18. Қалғанына 13 сағ, алғашқы 2-мен 15.","id":169},{"s":2,"l":"A","t":"Жолаушы екі қала арасында 120 км барды және сол жолмен қайтты. Бару жылдамдығы 60 км/сағ, қайту жылдамдығы 40 км/сағ.<br><br>Барып-қайту орташа жылдамдығы?","o":["50 км/сағ","48 км/сағ","45 км/сағ","52 км/сағ"],"a":1,"e":"Уақыт 2+3=5 сағ, жол 240.240/5=48.","id":170},{"s":2,"l":"A","t":"Жолаушы екі қала арасында 120 км барды және сол жолмен қайтты. Бару жылдамдығы 60 км/сағ, қайту жылдамдығы 40 км/сағ.<br><br>Барып-қайтуға 1 сағат аялдауды қоса есептегендегі орташа жылдамдық?","o":["40 км/сағ","50 км/сағ","48 км/сағ","44 км/сағ"],"a":0,"e":"Барлық уақыт 6 сағ.240/6=40.","id":171},{"s":2,"l":"B","t":"Жолаушы екі қала арасында 120 км барды және сол жолмен қайтты. Бару жылдамдығы 60 км/сағ, қайту жылдамдығы 40 км/сағ.<br><br>Қайту жылдамдығын 50 км/сағ-қа арттырмай,40-тан 50-ге өзгертсе, жалпы қозғалыс уақытынан қанша минут үнемдейді?","o":["24","36","30","40"],"a":1,"e":"Бұрын қайту 3 сағ, жаңасы 120/50=2,4 сағ. Үнем 0,6 сағ=36 мин.","id":172},{"s":2,"l":"B","t":"Жолаушы екі қала арасында 120 км барды және сол жолмен қайтты. Бару жылдамдығы 60 км/сағ, қайту жылдамдығы 40 км/сағ.<br><br>Бару 60 км/сағ болып қалсын. Орташа жылдамдықты 50 км/сағ ету үшін қайту жылдамдығы қанша? Аялдау жоқ.","o":["45 км/сағ","300/7 км/сағ","48 км/сағ","50 км/сағ"],"a":1,"e":"Жалпы уақыт 240/50=4,8 сағ. Қайту 2,8 сағ, жылдамдық 120/2,8=300/7.","id":173},{"s":2,"l":"C","t":"Жолаушы екі қала арасында 120 км барды және сол жолмен қайтты. Бару жылдамдығы 60 км/сағ, қайту жылдамдығы 40 км/сағ.<br><br>Қайтқанда жолдың жартысын 40 км/сағ, жартысын 60 км/сағ-пен жүрді. Барып-қайтудың жалпы орташа жылдамдығы?","o":["160/3 км/сағ","55 км/сағ","48 км/сағ","50 км/сағ"],"a":0,"e":"Бару 2 сағ. Қайту 60/40+60/60=2,5 сағ.240/4,5=160/3.","id":174},{"s":2,"l":"A","t":"Театр қатарларындағы орын саны арифметикалық прогрессия. Алғашқы 4 қатарда 96 орын, келесі 4 қатарда 144 орын бар.<br><br>Бірінші қатарда неше орын бар?","o":["Шарттар үйлеспейді","18","21","20"],"a":0,"e":"Екі блок қосындысының айырмасы 48=16d →d=3. Алғашқы 4:4a+6d=96 →a=19,5. Орын саны бүтін болуға тиіс, демек мәліметтер физикалық тұрғыдан үйлеспейді.","id":175},{"s":2,"l":"A","t":"Театр қатарларындағы орын саны арифметикалық прогрессия. Алғашқы 4 қатарда 96 орын, келесі 4 қатарда 144 орын бар.<br><br>Екі блоктағы бір қатарға шаққандағы орташа орын сандарының айырмасы неге тең?","o":["6","48","3","12"],"a":3,"e":"Орташа бірінші 96/4=24, екінші 144/4=36. Айырма 12.","id":176},{"s":2,"l":"B","t":"Театр қатарларындағы орын саны арифметикалық прогрессия. Алғашқы 4 қатарда 96 орын, келесі 4 қатарда 144 орын бар.<br><br>Егер бірінші 4 қатарда 102 орын, келесі 4 қатарда 150 орын болса, бірінші қатар неше орындық?","o":["19","18","24","21"],"a":3,"e":"Айырма 48→d=3.4a+18=102 →a=21.","id":177},{"s":2,"l":"C","t":"Театр қатарларындағы орын саны арифметикалық прогрессия. Алғашқы 4 қатарда 96 орын, келесі 4 қатарда 144 орын бар.<br><br>Түзетілген дерекпен алғашқы 10 қатардың барлық орнын сатты. Бір билет 2500 тг болса, түсім қанша?","o":["862500 тг","825000 тг","750000 тг","900000 тг"],"a":0,"e":"10-қатар 48. Қосынды 10(21+48)/2=345.345×2500=862500.","id":179},{"s":2,"l":"A","t":"ҚызметA: тапсырысқа 1800 тг және әр кмге 120 тг. ҚызметB: тапсырысқа 600 тг, алғашқы 5 км-ден кейінгі әр кмге 240 тг.5 км-ге дейінB тек 600 тг.<br><br>Қай қашықтықта екі қызметтің төлемі тең?","o":["10 км","25 км","15 км","20 км"],"a":3,"e":"x>5 үшін 1800+120x=600+240(x−5).2400=120x →x=20.","id":180},{"s":2,"l":"A","t":"ҚызметA: тапсырысқа 1800 тг және әр кмге 120 тг. ҚызметB: тапсырысқа 600 тг, алғашқы 5 км-ден кейінгі әр кмге 240 тг.5 км-ге дейінB тек 600 тг.<br><br>12 км үшінA қызметіB-ден қанша қымбат?","o":["960 тг","720 тг","1200 тг","480 тг"],"a":0,"e":"A3240. B600+7×240=2280. Айырма 960.","id":181},{"s":2,"l":"B","t":"ҚызметA: тапсырысқа 1800 тг және әр кмге 120 тг. ҚызметB: тапсырысқа 600 тг, алғашқы 5 км-ден кейінгі әр кмге 240 тг.5 км-ге дейінB тек 600 тг.<br><br>A қызметіне толық төлемнен 10% жеңілдік берілсе,25 км үшін қайсысы қаншаға арзан?","o":["A600 тг арзан","Бірдей","A1080 тг арзан","B1080 тг арзан"],"a":2,"e":"A4800×0,9=4320. B600+20×240=5400. Айырма 1080.","id":182},{"s":2,"l":"B","t":"ҚызметA: тапсырысқа 1800 тг және әр кмге 120 тг. ҚызметB: тапсырысқа 600 тг, алғашқы 5 км-ден кейінгі әр кмге 240 тг.5 км-ге дейінB тек 600 тг.<br><br>B қызметіне 5400 тг төленді. Жеткізу қашықтығы?","o":["22,5 км","25 км","30 км","20 км"],"a":1,"e":"(5400−600)/240=20 ақылы км, тегін 5 км қосылады:25.","id":183},{"s":2,"l":"C","t":"ҚызметA: тапсырысқа 1800 тг және әр кмге 120 тг. ҚызметB: тапсырысқа 600 тг, алғашқы 5 км-ден кейінгі әр кмге 240 тг.5 км-ге дейінB тек 600 тг.<br><br>A-ға 10% жеңілдік болса, бүтін километрмен қай қашықтықтан бастапA қатаң арзан?","o":["18 км","19 км","17 км","20 км"],"a":2,"e":"0,9(1800+120x)&lt;240x−600 →2220&lt;132x →x>16,818. Алғаш 17.","id":184},{"s":2,"l":"A","t":"Өзен ағысы 3 км/сағ. Қайық ағыспен 45 км-ді 3 сағатта жүрді. Қозғалыс жылдамдықтары тұрақты.<br><br>Сол 45 км-ді ағысқа қарсы жүру уақыты?","o":["4 сағат","5 сағат","3,75 сағат","6 сағат"],"a":1,"e":"Ағыспен 15, тынық суда 12, қарсы 9 км/сағ.45/9=5.","id":185},{"s":2,"l":"A","t":"Өзен ағысы 3 км/сағ. Қайық ағыспен 45 км-ді 3 сағатта жүрді. Қозғалыс жылдамдықтары тұрақты.<br><br>Сол қашықтыққа барып-қайтудың орташа жылдамдығы?","o":["11,25 км/сағ","10 км/сағ","13,5 км/сағ","12 км/сағ"],"a":0,"e":"Жол 90, уақыт 3+5=8.90/8=11,25.","id":186},{"s":2,"l":"B","t":"Өзен ағысы 3 км/сағ. Қайық ағыспен 45 км-ді 3 сағатта жүрді. Қозғалыс жылдамдықтары тұрақты.<br><br>Тынық судағы жылдамдық 20%-ға артты. Жаңа қарсы жылдамдық?","o":["11,4 км/сағ","14,4 км/сағ","10,8 км/сағ","12 км/сағ"],"a":0,"e":"Тынық су 12×1,2=14,4. Ағысты шегереміз:11,4.","id":187},{"s":2,"l":"B","t":"Өзен ағысы 3 км/сағ. Қайық ағыспен 45 км-ді 3 сағатта жүрді. Қозғалыс жылдамдықтары тұрақты.<br><br>Сал өзенмен ағыспен жүзіп барады. Қайық бастапқы нүктеден салдан 2 сағат кейін 15 км/сағ жерге қатысты жылдамдықпен шықты. Неше сағатта қуып жетеді?","o":["0,4","2","0,5","1"],"a":2,"e":"Сал 6 км озды. Салыстырмалы 15−3=12.6/12=0,5 сағ.","id":188},{"s":2,"l":"C","t":"Өзен ағысы 3 км/сағ. Қайық ағыспен 45 км-ді 3 сағатта жүрді. Қозғалыс жылдамдықтары тұрақты.<br><br>Қайық ағыспен 1 сағат жүріп, сол сәтте кері бұрылды. Бастапқы орынға қайта оралуға бұрылғаннан кейін неше сағат керек?","o":["5/3","2","4/3","1"],"a":0,"e":"Алға 15 км. Қарсы 9 км/сағ.15/9=5/3 сағ.","id":189},{"s":2,"l":"A","t":"Өнім саны бірінші күні 30, әр келесі күні алдыңғыдан 6-ға артық. Әр өнімді дайындауға 2 минут кетеді. Күндік жұмыс уақыты 4 сағаттан аспауы керек.<br><br>10-күнгі жұмыстың ұзақтығы?","o":["168 минут","156 минут","180 минут","120 минут"],"a":0,"e":"Өнім 30+9×6=84. Уақыт 84×2=168.","id":190},{"s":2,"l":"A","t":"Өнім саны бірінші күні 30, әр келесі күні алдыңғыдан 6-ға артық. Әр өнімді дайындауға 2 минут кетеді. Күндік жұмыс уақыты 4 сағаттан аспауы керек.<br><br>Күндік өнім саны алғаш 80-нен асатын күн?","o":["8-күн","9-күн","11-күн","10-күн"],"a":3,"e":"30+6(n−1)>80 →n>9,333. Алғаш 10.","id":191},{"s":2,"l":"B","t":"Өнім саны бірінші күні 30, әр келесі күні алдыңғыдан 6-ға артық. Әр өнімді дайындауға 2 минут кетеді. Күндік жұмыс уақыты 4 сағаттан аспауы керек.<br><br>4 сағаттық лимитке сыймайтын алғашқы күн?","o":["16-күн","18-күн","15-күн","17-күн"],"a":3,"e":"240 минутта 120 өнім.30+6(n−1)>120 →n>16. Алғаш 17.","id":192},{"s":2,"l":"B","t":"Өнім саны бірінші күні 30, әр келесі күні алдыңғыдан 6-ға артық. Әр өнімді дайындауға 2 минут кетеді. Күндік жұмыс уақыты 4 сағаттан аспауы керек.<br><br>Алғашқы 5 күнде жұмсалған жалпы уақыт?","o":["420 минут","450 минут","480 минут","360 минут"],"a":0,"e":"Өнім қосынды 5(30+54)/2=210. Уақыты 420 мин.","id":193},{"s":2,"l":"C","t":"Өнім саны бірінші күні 30, әр келесі күні алдыңғыдан 6-ға артық. Әр өнімді дайындауға 2 минут кетеді. Күндік жұмыс уақыты 4 сағаттан аспауы керек.<br><br>Алғашқы 10 күннің жиынтық өнімнің 10%-ы жарамсыз болды. Жарамды өнімдердің жалпы саны?","o":["500","540","570","513"],"a":3,"e":"Алғашқы 10 күндегі өнім 10(30+84)/2=570. Жиынтықтың 90%-ы 513, жарамсызы 57.","id":194},{"s":2,"l":"A","t":"А принтері 15 минут дайындалады, минутына 40 бет басады. B принтері 5 минут дайындалады, минутына 25 бет басады. Дайындық бір мезетте басталады.<br><br>А-ны жалғыз қолдануB-ны жалғыз қолданудан қай көлемнен бастап қатаң жылдам? Бүтін бет.","o":["666 бет","750 бет","600 бет","667 бет"],"a":3,"e":"15+n/40&lt;5+n/25 →10&lt;3n/200 →n>2000/3. Алғаш 667.","id":195},{"s":2,"l":"A","t":"А принтері 15 минут дайындалады, минутына 40 бет басады. B принтері 5 минут дайындалады, минутына 25 бет басады. Дайындық бір мезетте басталады.<br><br>Екеуі бірге 30 минут ішінде ең көбі неше бет басады?","o":["1000","1225","1950","1150"],"a":1,"e":"A15 мин×40=600,B25 мин×25=625. Қосынды 1225.","id":196},{"s":2,"l":"B","t":"А принтері 15 минут дайындалады, минутына 40 бет басады. B принтері 5 минут дайындалады, минутына 25 бет басады. Дайындық бір мезетте басталады.<br><br>900 беттің 500-і міндеттіA-да,400-і міндеттіB-де басылады. Толық жұмыс қашан аяқталады?","o":["25 минут","30 минут","21 минут","27,5 минут"],"a":3,"e":"A15+500/40=27,5. B5+400/25=21. Қатар істегендегі аяқталу — үлкені 27,5.","id":198},{"s":2,"l":"A","t":"Көлік 420 км жолдың алғашқы 180 км-ін 60 км/сағ жылдамдықпен жүрді. Қалған жолда жылдамдық 80 км/сағ болды.<br><br>Барлық қозғалыстың орташа жылдамдығы?","o":["68 км/сағ","75 км/сағ","72 км/сағ","70 км/сағ"],"a":3,"e":"180/60=3 сағ,240/80=3 сағ.420/6=70.","id":200},{"s":2,"l":"A","t":"Көлік 420 км жолдың алғашқы 180 км-ін 60 км/сағ жылдамдықпен жүрді. Қалған жолда жылдамдық 80 км/сағ болды.<br><br>Барлық сапарға 40 минут аялдауды қосқандағы орташа жылдамдық?","o":["63 км/сағ","60 км/сағ","66 км/сағ","65 км/сағ"],"a":0,"e":"Уақыт 6+2/3=20/3 сағ.420/(20/3)=63.","id":201},{"s":2,"l":"B","t":"Көлік 420 км жолдың алғашқы 180 км-ін 60 км/сағ жылдамдықпен жүрді. Қалған жолда жылдамдық 80 км/сағ болды.<br><br>Алғашқы 180 км бұрынғыдай қалсын. Бүкіл 420 км-ді 5 сағатта жүріп өтуге қалған жолдағы жылдамдық қанша болуы керек?","o":["110 км/сағ","100 км/сағ","120 км/сағ","96 км/сағ"],"a":2,"e":"Алғаш 3 сағ кетті,2 сағ қалды.240/2=120.","id":202},{"s":2,"l":"B","t":"Көлік 420 км жолдың алғашқы 180 км-ін 60 км/сағ жылдамдықпен жүрді. Қалған жолда жылдамдық 80 км/сағ болды.<br><br>Екі бөліктің де жылдамдығы 25%-ға артса, жалпы қозғалыс уақыты?","o":["5 сағат","4,5 сағат","7,5 сағат","4,8 сағат"],"a":3,"e":"Барлық бөліктің уақыты 1,25-ке бөлінеді:6/1,25=4,8.","id":203},{"s":2,"l":"C","t":"Көлік 420 км жолдың алғашқы 180 км-ін 60 км/сағ жылдамдықпен жүрді. Қалған жолда жылдамдық 80 км/сағ болды.<br><br>Алғашқы бөлік 60 км/сағ, кейінгі бөлікv. Жалпы орташа жылдамдық 75 км/сағ болуы үшінv қандай? Екі ондық таңбаға дейін.","o":["90 км/сағ","100 км/сағ","92,31 км/сағ","96 км/сағ"],"a":2,"e":"Қажет уақыт 420/75=5,6 сағ. Кейінгіге 2,6 сағ.240/2,6≈92,31.","id":204},{"s":2,"l":"A","t":"Шотта бастапқы 6000 тг. Әр апта соңында 3000 тг қосылады, әр үшінші аптада содан кейін 4500 тг алынады.<br><br>Алтыншы апта соңындағы сома?","o":["19500 тг","18000 тг","24000 тг","15000 тг"],"a":3,"e":"6000+6×3000−2×4500=15000.","id":205},{"s":2,"l":"B","t":"Шотта бастапқы 6000 тг. Әр апта соңында 3000 тг қосылады, әр үшінші аптада содан кейін 4500 тг алынады.<br><br>Тоғызыншы апта соңындағы сома сегізіншіден қаншаға өзгереді?","o":["1500 тг кемиді","3000 тг өседі","Өзгермейді","4500 тг кемиді"],"a":0,"e":"9-аптада+3000−4500=−1500.","id":207},{"s":2,"l":"B","t":"Шотта бастапқы 6000 тг. Әр апта соңында 3000 тг қосылады, әр үшінші аптада содан кейін 4500 тг алынады.<br><br>Алғашқы 12 аптадағы таза өсім?","o":["36000 тг","22500 тг","18000 тг","24000 тг"],"a":2,"e":"12×3000−4×4500=18000. Бастапқы 6000 өсімге кірмейді.","id":208},{"s":3,"l":"A","t":"Тіктөртбұрышты бақтың ұзындығы енінен 6 м артық. Ішкі шетін бойлай ені 1 м жол салынғанда ортасында 72 м² көгал қалды.<br><br>Бақтың бастапқы ені?","o":["8 м","10 м","7 м","9 м"],"a":0,"e":"(w−2)(w+4)=72 →w²+2w−80=0 →(w+10)(w−8)=0. Оң шешімw=8 м.","id":210},{"s":3,"l":"A","t":"Тіктөртбұрышты бақтың ұзындығы енінен 6 м артық. Ішкі шетін бойлай ені 1 м жол салынғанда ортасында 72 м² көгал қалды.<br><br>Ені 8 м, ұзындығы 14 м деп бөлек берілсе, ені 1 м ішкі жолдан кейінгі көгал ауданы?","o":["60 м²","84 м²","72 м²","96 м²"],"a":2,"e":"(8−2)(14−2)=6×12=72.","id":211},{"s":3,"l":"B","t":"Тіктөртбұрышты бақтың ұзындығы енінен 6 м артық. Ішкі шетін бойлай ені 1 м жол салынғанда ортасында 72 м² көгал қалды.<br><br>Ені 8, ұзындығы 14 м бақтағы 1 м ішкі жол ауданы?","o":["36 м²","44 м²","40 м²","48 м²"],"a":2,"e":"Бастапқы 112, көгал 72. Айырма 40.","id":212},{"s":3,"l":"B","t":"Тіктөртбұрышты бақтың ұзындығы енінен 6 м артық. Ішкі шетін бойлай ені 1 м жол салынғанда ортасында 72 м² көгал қалды.<br><br>Осы 40 м² жолға 0,2×0,5 м плитка кесусіз аудан бойынша төселеді.10% қорымен неше дана керек?","o":["420","400","450","440"],"a":3,"e":"Бір плитка 0,1 м², таза 400.1,1×400=440.","id":213},{"s":3,"l":"C","t":"Тіктөртбұрышты бақтың ұзындығы енінен 6 м артық. Ішкі шетін бойлай ені 1 м жол салынғанда ортасында 72 м² көгал қалды.<br><br>Осы 8×14 м баққа ені 2 м жолды ішінен емес, сыртынан салса, жолдың өз ауданы қанша?","o":["96 м²","104 м²","88 м²","112 м²"],"a":1,"e":"Сыртқы 12×18=216, бақ 112. Жол 104. Бұрыштарды ескеру қажет.","id":214},{"s":3,"l":"A","t":"Тікбұрышты қорап ұзындығы енінен 3 есе, биіктігі енінен 2 см артық. Түбінің ауданы 48 см².<br><br>Қорап көлемі?","o":["384 см³","192 см³","240 см³","288 см³"],"a":3,"e":"3w²=48 →w=4,l=12,h=6. Көлем 12×4×6=288.","id":215},{"s":3,"l":"A","t":"Тікбұрышты қорап ұзындығы енінен 3 есе, биіктігі енінен 2 см артық. Түбінің ауданы 48 см².<br><br>Толық бетінің ауданы?","o":["336 см²","192 см²","240 см²","288 см²"],"a":3,"e":"2(48+72+24)=288.","id":216},{"s":3,"l":"B","t":"Тікбұрышты қорап ұзындығы енінен 3 есе, биіктігі енінен 2 см артық. Түбінің ауданы 48 см².<br><br>Қақпақсыз қорапқа 10% қорымен қажет қағаз ауданы?","o":["316,8 см²","288 см²","264 см²","240 см²"],"a":2,"e":"Қақпақсыз 288−48=240.×1,1=264.","id":217},{"s":3,"l":"B","t":"Тікбұрышты қорап ұзындығы енінен 3 есе, биіктігі енінен 2 см артық. Түбінің ауданы 48 см².<br><br>Ұзындығы мен ені өзгермей, көлемді 25%-ға арттыру үшін биіктікті қаншаға арттыру керек?","o":["1 см","3 см","1,5 см","2 см"],"a":2,"e":"Биіктік те 25%-ға артады:6×0,25=1,5.","id":218},{"s":3,"l":"C","t":"Тікбұрышты қорап ұзындығы енінен 3 есе, биіктігі енінен 2 см артық. Түбінің ауданы 48 см².<br><br>Ені мен ұзындығы екі есе қысқарды. Көлем 288 см³ болып қалуы үшін биіктік қанша болуы тиіс?","o":["24 см","36 см","12 см","18 см"],"a":0,"e":"Түп ауданы 48/4=12. h=288/12=24.","id":219},{"s":3,"l":"A","t":"Қыры 6 см текше сыртынан боялып, бірлік текшелерге бөлінді. Бірлік текшелер кездейсоқ тең ықтималдықпен таңдалады.<br><br>Дәл бір беті боялған текше саны?","o":["96","144","48","64"],"a":0,"e":"Әр 6 беттің ішкі 4×4 бөліктері:6×16=96.","id":220},{"s":3,"l":"A","t":"Қыры 6 см текше сыртынан боялып, бірлік текшелерге бөлінді. Бірлік текшелер кездейсоқ тең ықтималдықпен таңдалады.<br><br>Бір де бір беті боялмаған болу ықтималдығы?","o":["1/4","8/27","1/3","4/9"],"a":1,"e":"Ішкі(6−2)³=64, барлығы 216.64/216=8/27.","id":221},{"s":3,"l":"B","t":"Қыры 6 см текше сыртынан боялып, бірлік текшелерге бөлінді. Бірлік текшелер кездейсоқ тең ықтималдықпен таңдалады.<br><br>Кемінде екі беті боялған текше саны?","o":["64","72","48","56"],"a":3,"e":"Дәл екі бет:12×4=48. Үш бет:8 бұрыш. Барлығы 56.","id":222},{"s":3,"l":"B","t":"Қыры 6 см текше сыртынан боялып, бірлік текшелерге бөлінді. Бірлік текшелер кездейсоқ тең ықтималдықпен таңдалады.<br><br>Кемінде бір беті боялғаны белгілі. Оның дәл үш беті боялған болу ықтималдығы?","o":["1/19","1/18","1/9","1/27"],"a":0,"e":"Боялған 216−64=152. Үш бет 8.8/152=1/19.","id":223},{"s":3,"l":"C","t":"Қыры 6 см текше сыртынан боялып, бірлік текшелерге бөлінді. Бірлік текшелер кездейсоқ тең ықтималдықпен таңдалады.<br><br>Дәл бір беті боялған текше алынып тасталды. Қалғанынан біреуін алғанда еш боялмаған текше болу ықтималдығы?","o":["64/215","8/27","63/215","64/216"],"a":0,"e":"Алынған бояулы, сондықтан ішкі 64 өзгермейді, жалпы 215 қалады.","id":224},{"s":3,"l":"A","t":"Цилиндр ыдыстың радиусы 4 см. Су биіктігі 15 см. π=3. Ыдыс қабырғасы тік, қалыңдығы ескерілмейді.<br><br>Судың жартысын радиусы 2 см цилиндрге құйғанда жаңа ыдыстағы биіктік?","o":["60 см","15 см","7,5 см","30 см"],"a":3,"e":"Бастапқы көлем 3×16×15=720. Жарты 360. Жаңа түп 3×4=12. Биіктік 30.","id":225},{"s":3,"l":"A","t":"Цилиндр ыдыстың радиусы 4 см. Су биіктігі 15 см. π=3. Ыдыс қабырғасы тік, қалыңдығы ескерілмейді.<br><br>Бастапқы ыдысқа көлемі 96 см³ дене толық батырылса, деңгей қаншаға көтеріледі?","o":["2 см","4 см","3 см","1 см"],"a":0,"e":"Түп 48 см², өсім 96/48=2.","id":226},{"s":3,"l":"C","t":"Цилиндр ыдыстың радиусы 4 см. Су биіктігі 15 см. π=3. Ыдыс қабырғасы тік, қалыңдығы ескерілмейді.<br><br>Ыдыс бастапқы 15 см деңгейде.2 см көтерілу туғызатын металл текшенің қыры қанша? Куб түбір түрінде таңдаңыз.","o":["∛48 см","∛96 см","4 см","6 см"],"a":1,"e":"Ығыстырылған көлем 48×2=96 см³, толық батқан текшенің қыры∛96.","id":229},{"s":3,"l":"A","t":"Картада тіктөртбұрыш жер ауданы 15 см². Масштаб 1:4000. Жоспардағы ұзындығы енінен 2/3 есе артық, яғни 5/3 бөлігі.<br><br>Нақты жердің ені мен ұзындығы?","o":["160 м және 240 м","120 м және 200 м","100 м және 150 м","80 м және 120 м"],"a":1,"e":"w×5w/3=15 →w=3 см,l=5 см. Бір см 40 м, сондықтан 120 және 200 м.","id":230},{"s":3,"l":"A","t":"Картада тіктөртбұрыш жер ауданы 15 см². Масштаб 1:4000. Жоспардағы ұзындығы енінен 2/3 есе артық, яғни 5/3 бөлігі.<br><br>Нақты аудан гектармен?","o":["2,4 га","24 га","0,24 га","6 га"],"a":0,"e":"120×200=24000 м²,10000 м²=1 га →2,4.","id":231},{"s":3,"l":"B","t":"Картада тіктөртбұрыш жер ауданы 15 см². Масштаб 1:4000. Жоспардағы ұзындығы енінен 2/3 есе артық, яғни 5/3 бөлігі.<br><br>Жерді ұзындығы бойымен тең 3 бөлікке бөліп, бөлетін екі сызықтың әрқайсысы ені 120 м-ге параллель жүргізілді. Сыртқы қоршаумен бірге барлық қоршау?","o":["880 м","640 м","1040 м","760 м"],"a":0,"e":"Сыртқы 2(120+200)=640. Екі ішкі 120+120=240. Барлығы 880.","id":232},{"s":3,"l":"B","t":"Картада тіктөртбұрыш жер ауданы 15 см². Масштаб 1:4000. Жоспардағы ұзындығы енінен 2/3 есе артық, яғни 5/3 бөлігі.<br><br>Карта масштабы 1:2000 болып қайта салынса, сол жердің картадағы ауданы?","o":["60 см²","30 см²","15 см²","120 см²"],"a":0,"e":"Сызықтық өлшем 2 есе, аудан 4 есе:15×4=60.","id":233},{"s":3,"l":"C","t":"Картада тіктөртбұрыш жер ауданы 15 см². Масштаб 1:4000. Жоспардағы ұзындығы енінен 2/3 есе артық, яғни 5/3 бөлігі.<br><br>Нақты жердің ішкі шетінен барлық жақта ені 10 м жол қалды. Қалған аудан неше гектар?","o":["1,8 га","1,6 га","2 га","1,9 га"],"a":0,"e":"Ішкі өлшем 100×180=18000 м²=1,8 га.","id":234},{"s":3,"l":"A","t":"Екі ұқсас үшбұрыштың периметрлері 24 және 40 см. Кіші үшбұрыш ауданы 24 см².<br><br>Үлкен үшбұрыш ауданы?","o":["200/3 см²","40 см²","60 см²","80 см²"],"a":0,"e":"Периметр қатынасы 5/3, аудан қатынасы 25/9.24×25/9=200/3 см².","id":235},{"s":3,"l":"A","t":"Екі ұқсас үшбұрыштың периметрлері 24 және 40 см. Кіші үшбұрыш ауданы 24 см².<br><br>Үлкенінің сәйкес биіктігі кіші биіктіктен 4 см артық. Кіші биіктік?","o":["6 см","8 см","10 см","12 см"],"a":0,"e":"h×(5/3−1)=4 →2h/3=4 →h=6. Мысалы 6,8,10 қабырғалы үшбұрыш осы шарттармен үйлеседі.","id":236},{"s":3,"l":"B","t":"Екі ұқсас үшбұрыштың периметрлері 24 және 40 см. Кіші үшбұрыш ауданы 24 см².<br><br>Осы кіші үшбұрыштың 6 см биіктігіне сәйкес табаны?","o":["8 см","6 см","9 см","12 см"],"a":0,"e":"Кіші аудан 24, биіктік 6. Табан 2×24/6=8 см.","id":237},{"s":3,"l":"B","t":"Екі ұқсас үшбұрыштың периметрлері 24 және 40 см. Кіші үшбұрыш ауданы 24 см².<br><br>Үлкеннің сәйкес табаны?","o":["40/3 см","15 см","12 см","16 см"],"a":0,"e":"Кіші табан 8, сызықтық коэффициент 5/3. Үлкен табан 8×5/3=40/3 см.","id":238},{"s":3,"l":"C","t":"Екі ұқсас үшбұрыштың периметрлері 24 және 40 см. Кіші үшбұрыш ауданы 24 см².<br><br>Ауданы 200/3 см² үлкен үшбұрыштың әр сызықтық өлшемі 20%-ға қысқарса, жаңа аудан?","o":["128/3 см²","160/3 см²","40 см²","48 см²"],"a":0,"e":"Жаңа аудан(200/3)×0,8²=(200/3)×0,64=128/3 см².","id":239},{"s":3,"l":"A","t":"Тіктөртбұрыштың периметрі 50 м. Ұзындығы енінен 5 м артық.<br><br>Ауданы?","o":["125 м²","150 м²","140 м²","156,25 м²"],"a":1,"e":"l+w=25,l−w=5 →l15,w10. Аудан 150.","id":240},{"s":3,"l":"A","t":"Тіктөртбұрыштың периметрі 50 м. Ұзындығы енінен 5 м артық.<br><br>Диагоналі дәл қандай?","o":["5√13 м","25 м","5√5 м","20 м"],"a":0,"e":"√(15²+10²)=√325=5√13.","id":241},{"s":3,"l":"B","t":"Тіктөртбұрыштың периметрі 50 м. Ұзындығы енінен 5 м артық.<br><br>Ұзындығын 2 м-ге қысқартып, енін 2 м-ге ұлғайтқанда аудан қаншаға өседі?","o":["8 м²","4 м²","10 м²","6 м²"],"a":3,"e":"Жаңа 13×12=156.156−150=6.","id":242},{"s":3,"l":"B","t":"Тіктөртбұрыштың периметрі 50 м. Ұзындығы енінен 5 м артық.<br><br>Периметрі 50 м болатын тіктөртбұрыштың ең үлкен мүмкін ауданы?","o":["150 м²","162,5 м²","156,25 м²","144 м²"],"a":2,"e":"Қосынды 25 тұрақты, көбейтінді тең қабырғаларда ең үлкен:12,5²=156,25.","id":243},{"s":3,"l":"C","t":"Тіктөртбұрыштың периметрі 50 м. Ұзындығы енінен 5 м артық.<br><br>Қабырғалары бүтін метрмен өлшенсе, осы периметрмен ең үлкен аудан?","o":["154 м²","150 м²","156 м²","156,25 м²"],"a":2,"e":"Қосынды 25 болғандағы ең жақын бүтіндер 12 және 13. Аудан 156.","id":244},{"s":3,"l":"A","t":"Пицца радиусы 12 см, оның бағасы 3600 тг. Екінші пиццаның радиусы 18 см, бағасы 7200 тг. Қалыңдықтары тең.<br><br>Екі кіші пиццаның ауданы бір үлкеннің ауданының қандай бөлігі?","o":["2/3","8/9","3/4","1"],"a":1,"e":"2π12²/(π18²)=288/324=8/9.","id":245},{"s":3,"l":"A","t":"Пицца радиусы 12 см, оның бағасы 3600 тг. Екінші пиццаның радиусы 18 см, бағасы 7200 тг. Қалыңдықтары тең.<br><br>Бір теңгеге шаққандағы аудан бойынша үлкен пицца кішіден неше пайыз тиімді?","o":["50%","25%","10%","12,5%"],"a":3,"e":"Үлкендеаудан 2,25 есе, баға 2 есе. Аудан/баға 1,125 есе, тиімділік 12,5% артық.","id":246},{"s":3,"l":"B","t":"Пицца радиусы 12 см, оның бағасы 3600 тг. Екінші пиццаның радиусы 18 см, бағасы 7200 тг. Қалыңдықтары тең.<br><br>Үлкен пиццаны 8 тең секторға бөлді. Бір сектор ауданы кіші пиццаның қандай бөлігі?","o":["1/4","3/8","2/9","9/32"],"a":3,"e":"(π18²/8)/(π12²)=324/(8×144)=9/32.","id":247},{"s":3,"l":"C","t":"Пицца радиусы 12 см, оның бағасы 3600 тг. Екінші пиццаның радиусы 18 см, бағасы 7200 тг. Қалыңдықтары тең.<br><br>Үлкен пиццадан радиусы 6 см орталық дөңгелек бөлік алынды. Қалған сақинаның ауданы неше кіші пицца ауданына тең?","o":["2,25","1,5","2","3"],"a":2,"e":"π(18²−6²)/(π12²)=(324−36)/144=2.","id":249},{"s":3,"l":"A","t":"Қорап түбі 12×8 см. Қақпақсыз қораптың толық бетінің ауданы 296 см².<br><br>Биіктігі?","o":["8 см","5 см","4 см","6 см"],"a":1,"e":"Түп 96, бүйірлер 2(12+8)h=40h.96+40h=296 →h=5.","id":250},{"s":3,"l":"A","t":"Қорап түбі 12×8 см. Қақпақсыз қораптың толық бетінің ауданы 296 см².<br><br>Көлемі?","o":["384 см³","480 см³","960 см³","576 см³"],"a":1,"e":"12×8×5=480.","id":251},{"s":3,"l":"B","t":"Қорап түбі 12×8 см. Қақпақсыз қораптың толық бетінің ауданы 296 см².<br><br>Қақпақ қосылса, толық бет ауданы қанша пайызға өседі? Ондыққа дейін.","o":["25%","40%","32,4%","24,5%"],"a":2,"e":"Қосылатын 96 см².96/296×100≈32,4%.","id":252},{"s":3,"l":"B","t":"Қорап түбі 12×8 см. Қақпақсыз қораптың толық бетінің ауданы 296 см².<br><br>Түп өлшемдері өзгермей, биіктік 2 есе өссе, қақпақсыз бет ауданы?","o":["392 см²","592 см²","480 см²","496 см²"],"a":3,"e":"Түп 96 өзгермейді, бүйірлер 200×2=400. Барлығы 496.","id":253},{"s":3,"l":"C","t":"Қорап түбі 12×8 см. Қақпақсыз қораптың толық бетінің ауданы 296 см².<br><br>Қорап табанына параллель ортадан кесілді. Қалыңдық ескерілмейді, кесілген жерлерге жаңа түп не қақпақ қойылмайды. Екі бөліктегі бар материал беттерінің аудандарының қосындысы?","o":["296 см²","488 см²","392 см²","592 см²"],"a":0,"e":"Кесу көлденең бет материалын қоспайды: қабырғалар тек екіге бөлінді, бір түп сол күйі қалды. Бет аудандары қосындысы 296. Жаңа қақпақтар салынбаған.","id":254},{"s":3,"l":"A","t":"Дене 4×4×4 бірлік текшеден құралған үлкен текше. Оның бір бұрышындағы 2×2×2 шағын текшелік блок алынып тасталды.<br><br>Қалған көлем?","o":["56 бірлік³","60 бірлік³","52 бірлік³","48 бірлік³"],"a":0,"e":"Бастапқы 64, алынған 8.64−8=56.","id":255},{"s":3,"l":"A","t":"Дене 4×4×4 бірлік текшеден құралған үлкен текше. Оның бір бұрышындағы 2×2×2 шағын текшелік блок алынып тасталды.<br><br>Бастапқы толық бет ауданы?","o":["64 бірлік²","96 бірлік²","48 бірлік²","128 бірлік²"],"a":1,"e":"Бастапқы текшенің алты жағы бар, әр жақ ауданы 4²=16. Толық бет ауданы 6×16=96 бірлік².","id":256},{"s":3,"l":"B","t":"Дене 4×4×4 бірлік текшеден құралған үлкен текше. Оның бір бұрышындағы 2×2×2 шағын текшелік блок алынып тасталды.<br><br>Бұрыштық блок алынғаннан кейінгі толық бет ауданы?","o":["120 бірлік²","72 бірлік²","96 бірлік²","84 бірлік²"],"a":2,"e":"Сыртқы 3 беттен 3×4=12 аудан жоғалады, іштен дәл 3×4=12 ашылады. Нетто өзгеріс 0.","id":257},{"s":3,"l":"B","t":"Дене 4×4×4 бірлік текшеден құралған үлкен текше. Оның бір бұрышындағы 2×2×2 шағын текшелік блок алынып тасталды.<br><br>Қалған дене көлемінің бастапқыға қатынасы?","o":["3/4","5/6","4/5","7/8"],"a":3,"e":"Бастапқы көлем 4³=64. Алынған блок көлемі 2³=8. Қалған көлем 64−8=56, бастапқыға қатынасы 56/64=7/8.","id":258},{"s":3,"l":"C","t":"Дене 4×4×4 бірлік текшеден құралған үлкен текше. Оның бір бұрышындағы 2×2×2 шағын текшелік блок алынып тасталды.<br><br>Алынған 2×2×2 блокты бөлек қойып, екі дененің барлық бет аудандарын қоссақ, бастапқыдан қаншаға артық?","o":["0","48 бірлік²","12 бірлік²","24 бірлік²"],"a":3,"e":"Қалғанның беті 96, бөлекблок 24. Барлығы 120, бастапқы 96-дан 24 артық. Кесу арқылы 6 жаңа 2×2 бет пайда болады.","id":259}];
